#include <bits/stdc++.h>
using namespace std;

const long long MODULUS = 998244353;
vector<long long> rootW(21), rootWInverse(21);

long long modPow(long long base, long long exp) {
    long long result = 1;
    long long baseLong = base % MODULUS;
    long long e = exp;
    while (e > 0) {
        if (e & 1)
            result = (result * baseLong) % MODULUS;
        baseLong = (baseLong * baseLong) % MODULUS;
        e >>= 1;
    }
    return result;
}

void prepareRoots() {
    for (int h = 0; h <= 20; h++) {
        rootW[h] = modPow(3, (MODULUS - 1) >> h);
        rootWInverse[h] = modPow(3, (MODULUS - 1) - ((MODULUS - 1) >> h));
    }
}

void fftProcess(vector<long long>& data, int length, bool invert) {
    for (int i = 1, j = 0; i < length; i++) {
        int mask = length;
        do {
            j ^= mask >>= 1;
        } while ((j & mask) == 0);
        if (i < j) {
            swap(data[i], data[j]);
        }
    }
    for (int h = 0, size; (size = 1 << h) < length; h++) {
        long long wRoot = invert ? rootWInverse[h + 1] : rootW[h + 1];
        for (int startIdx = 0; startIdx < length; startIdx += size * 2) {
            long long w = 1;
            for (int j = 0; j < size; j++) {
                int leftIdx = startIdx + j, rightIdx = leftIdx + size;
                long long u = data[leftIdx], v = data[rightIdx] * w % MODULUS;
                data[leftIdx] = (u + v) % MODULUS;
                data[rightIdx] = (u - v + MODULUS) % MODULUS;
                w = (w * wRoot) % MODULUS;
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    prepareRoots();

    int nHalfVal, kCount;
    cin >> nHalfVal >> kCount;
    int sizeN = 1;
    while (sizeN < nHalfVal * 9 + 1)
        sizeN <<= 1;

    vector<long long> arrayData(sizeN, 0);
    for (int i = 0; i < kCount; i++) {
        int d;
        cin >> d;
        arrayData[d] = 1;
    }

    fftProcess(arrayData, sizeN, false);
    for (int i = 0; i < sizeN; i++) {
        arrayData[i] = modPow(arrayData[i], nHalfVal);
    }
    fftProcess(arrayData, sizeN, true);

    long long invN = modPow(sizeN, MODULUS - 2);
    for (int i = 0; i < sizeN; i++) {
        arrayData[i] = (arrayData[i] * invN) % MODULUS;
    }

    long long totalSum = 0;
    for (int i = 0; i <= nHalfVal * 9; i++) {
        long long val = arrayData[i];
        totalSum = (totalSum + val * val) % MODULUS;
    }

    cout << totalSum << "\n";

    return 0;
}
